	// --- Assets ---

	/**
	 * Cache-busting versija asset'ams pagal failo modifikavimo laika (filemtime).
	 * Kiekvienas failas gauna savo versija -> pakeitus faila, narsykle uzsikrauna
	 * nauja be Ctrl+Shift+R. Jei failo nera -> grazina statine VERSION.
	 */
	private static function asset_ver( $rel ) {
		$path = dirname( __DIR__ ) . '/assets/' . $rel;
		$mt   = @filemtime( $path );
		return $mt ? (string) $mt : self::VERSION;
	}

